<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $group = $args['group']; ?><article class="sd-group-card"><a class="sd-group-card-cover" href="<?php echo esc_url( sd_group_url( $group->id ) ); ?>"><?php if ( function_exists( 'bp_group_cover_url' ) && bp_group_cover_url( $group ) ) : ?><img src="<?php echo esc_url( bp_group_cover_url( $group ) ); ?>" alt="" loading="lazy"><?php endif; ?></a><div class="sd-group-card-body"><span class="sd-badge"><?php echo esc_html( ucfirst( $group->status ) ); ?></span><h2><a href="<?php echo esc_url( sd_group_url( $group->id ) ); ?>"><?php echo esc_html( bp_get_group_name( $group ) ); ?></a></h2><p><?php echo esc_html( wp_trim_words( bp_get_group_description( $group ), 22 ) ); ?></p><div class="sd-group-meta"><span><?php echo esc_html( absint( $group->total_member_count ) ); ?> <?php esc_html_e( 'members', 'social-discovery' ); ?></span><a class="sd-button sd-button-outline" href="<?php echo esc_url( sd_group_url( $group->id ) ); ?>"><?php esc_html_e( 'View community', 'social-discovery' ); ?></a></div></div></article>
